def process_string() -> None:
    s = input()
    uppercase_count = 0
    lowercase_count = 0
    for c in s:
        if c.isupper():
            uppercase_count += 1
        elif c.islower():
            lowercase_count += 1
    if uppercase_count > lowercase_count:
        s = s.upper()
    else:
        s = s.lower()
    print(s)
